  if (id === PUBLIC_PRESET_ACANTHOSTEGA_COMPOSITION_MERGE || id.includes('COMPOSITION_MERGE')) return UI_PRESET_ACANTHOSTEGA_COMPOSITION_MERGE;
  if (id === PUBLIC_PRESET_ACANTHOSTEGA_BRING_TOGETHER || id.includes('BRING')) {
    return UI_PRESET_ACANTHOSTEGA_BRING_TOGETHER;
  }
  if (id === PUBLIC_PRESET_ACANTHOSTEGA_BILATERAL_GRASP || id.includes('BILATERAL')) {
    return UI_PRESET_ACANTHOSTEGA_BILATERAL_GRASP;
  }
  if (id === PUBLIC_PRESET_ACANTHOSTEGA_SINGLE_GRASP || id.includes('GRASP')) {
    return UI_PRESET_ACANTHOSTEGA_SINGLE_GRASP;
  }
  if (id === PUBLIC_PRESET_ACANTHOSTEGA_MATERIAL_VISION || (id.includes('MATERIAL') && id.includes('VISION'))) {
    return UI_PRESET_ACANTHOSTEGA_MATERIAL_VISION;
  }
  if (id === PUBLIC_PRESET_ACANTHOSTEGA_MATERIALS || (id.includes('MATERIALS') && !id.includes('VISION'))) {
    return UI_PRESET_ACANTHOSTEGA_MATERIALS;
  }
