export function presetModifiedStatusLabel(preset: string, modified: boolean): string {
  if (preset === UI_PRESET_CUSTOM) return 'CUSTOM';
  return modified ? `${preset} — Modified` : preset;
}

export function compatPublicPreset(raw: string | null | undefined): 'TIKTAALIK' | 'ACANTHOSTEGA' {
  if (raw == null || String(raw).trim() === '') return 'TIKTAALIK';
  return modelLineFromPublicPreset(raw);
}
